let seed = Math.random() * 9999;
let num = 12;
let radius, mySize;
let v_planet = [];
let trails = [];
let t = 0;
let colors = [];
let bgColor;

function setup() {

	randomSeed(seed);
	noiseSeed(seed);
	createCanvas(windowWidth, windowHeight, WEBGL);
	angleMode(RADIANS);
	mySize = max(windowWidth, windowHeight);
	radius = mySize * 0.5;

	colors = random(colorScheme).colors;
	colorbg = random(bgcolor)
	background(colorbg);

	for (let i = 0; i < num; i++) {
		trails.push([]);
	}
}

function draw() {
	randomSeed(seed);
	background(colorbg);
	// orbitControl(); // 允许鼠标3D控制

	let layerCount = 2;//int(random(3, 2)); // 星环层数
	let R = radius * 1.2;

	for (let i = 0; i < num; i++) {
		let layer = i % layerCount;
		let layerAngleOffset = (TWO_PI / layerCount) * layer;
		let baseAngle = (TWO_PI / num) * i + t * 0.5;

		let spiralRadius = R * (0.4 + 0.2 * sin(t + i)); // 每层大小波动
		let heightOffset = sin(t * 0.7 + i) * radius * 0.2;

		// 生成球面坐标上的点
		let theta = baseAngle + layerAngleOffset;
		let phi = t + i * 0.5;

		let x = spiralRadius * sin(theta) * cos(phi);
		let y = spiralRadius * sin(theta) * sin(phi);
		let z = spiralRadius * cos(theta) + heightOffset;

		let p = createVector(x, y, z);
		v_planet[i] = p;
		trails[i].push(p.copy());

		if (trails[i].length > 120) trails[i].shift();
	}

	// 绘制轨迹
	for (let i = 0; i < num; i++) {
		push();
		rotateX(random(TAU) * 1 + frameCount / 100);
		rotateY(random(TAU) * 1 + frameCount / 100);
		rotateZ(random(TAU) * 1 + frameCount / 100);
		let c = color(colors[i % colors.length]);
		c.setAlpha(255);
		stroke(c);
		strokeWeight(20);
		noFill();
		beginShape();
		for (let v of trails[i]) {
			vertex(v.x, v.y, v.z);
		}
		endShape();
		pop();
	}

	// 行星本体（可关闭）
	for (let i = 0; i < num; i++) {
		push();
		rotateX(random(TAU) * 1 + frameCount / 100);
		rotateY(random(TAU) * 1 + frameCount / 100);
		rotateZ(random(TAU) * 1 + frameCount / 100);
		var c = color(colors[i % colors.length]);
		fill(c);
		noStroke();
		translate(v_planet[i].x, v_planet[i].y, v_planet[i].z);
		sphere(10);
		pop();
	}


	t += 0.01;
}

