<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Radial Январь</title>
<style>
  :root { color-scheme: dark; }
  body { margin:0; padding:18px; background:#0c0c0f; color:#f3f3f3; font-family: system-ui, -apple-system, Segoe UI, Roboto, monospace; }
  h1 { font-size:20px; margin:0 0 12px; }
  .layout { display:grid; grid-template-columns: 320px 1fr; gap:14px; }
  .panel { background:#15151a; border:1px solid #2a2a31; border-radius:12px; padding:12px; }
  label { font-size:12px; opacity:.9; display:block; margin-top:8px; }
  input[type=color], select, input[type=range], input[type=number], button, textarea { width:100%; background:#121218; color:#fff; border:1px solid #2a2a31; border-radius:10px; padding:8px; }
  textarea { height:110px; resize:vertical; }
  .row { display:flex; gap:8px; }
  canvas { width:100%; height:auto; background:#000; border:1px solid #2a2a31; border-radius:12px; }
  .hint { font-size:12px; opacity:.7; margin-top:8px; }
  .grid2 { display:grid; grid-template-columns: 1fr 1fr; gap:8px; }
</style>
</head>
<body>
<h1>Radial — Январь</h1>
<div class="layout">
  <div class="panel">
    <label>Текст</label>
    <textarea id="text">ян\nва\nрь</textarea>

    <div class="grid2">
      <div>
        <label>Шрифт</label>
        <select id="fontFamily">
          <option value="Arial, sans-serif" selected>Arial</option>
          <option value="Courier New, monospace">Courier New</option>
          <option value="Georgia, serif">Georgia</option>
        </select>
      </div>
      <div>
        <label>Начальный размер (px)</label>
        <input id="fontSize" type="number" value="320">
      </div>
    </div>

    <div class="row">
      <label style="flex:1"><input type="checkbox" id="bold"> Жирный</label>
      <label style="flex:1"><input type="checkbox" id="autoFit" checked> Авто-подгон по ширине</label>
    </div>

    <label>Поля (%)</label>
    <input id="paddingPct" type="range" min="0" max="20" value="5">

    <hr style="border:none; border-top:1px solid #27272f; margin:10px 0">

    <label>Цветовая палитра</label>
    <select id="palette">
      <option value="mono">Моно (белый)</option>
      <option value="neon">Неон</option>
      <option value="stripes" selected>Полосы</option>
    </select>

    <label>Скорость анимации</label>
    <input id="speed" type="range" min="0.2" max="4" step="0.1" value="1.5">

    <hr style="border:none; border-top:1px solid #27272f; margin:10px 0">

    <label>Цвет чисел</label>
    <input id="numColor" type="color" value="#00ffff">

    <label>Размер чисел (px)</label>
    <input id="numSize" type="range" min="10" max="60" value="26">

    <label>Охранное поле (%)</label>
    <input id="numMargin" type="range" min="0" max="15" value="3">

    <button id="download">⬇ Скачать PNG</button>
  </div>

  <div class="panel">
    <canvas id="cv" width="1400" height="1800"></canvas>
  </div>
</div>

<script>
const cv = document.getElementById('cv');
const ctx = cv.getContext('2d', { willReadFrequently: true });
const W = cv.width;
const H = cv.height;

const src = document.createElement('canvas');
const sctx = src.getContext('2d', { willReadFrequently: true });
const els = Object.fromEntries(Array.from(document.querySelectorAll('input, select, textarea, button')).map(e=>[e.id,e]));
const center = {x: W/2, y: H/2};

// Палитра "Полосы" (по референсу)
const stripeColors = ['#3b4da0', '#b93982', '#4caf50', '#f7e85b'];

// === Числа 1–31 по периметру ===
function drawNumbersAround(time, color, size, marginPct) {
  const count = 31;
  const margin = Math.min(W, H) * (marginPct / 100);
  const per = 2 * ((W - 2*margin) + (H - 2*margin));
  const speed = 2;
  const move = (time * speed * 40) % per;
  const step = per / count;

  ctx.save();
  ctx.font = `${size}px Arial, sans-serif`;
  ctx.fillStyle = color;

  for (let i = 0; i < count; i++) {
    let pos = (move + i * step) % per;
    var x, y;

    if (pos < (W - 2*margin)) { x = margin + pos; y = margin; }
    else if (pos < (W - 2*margin) + (H - 2*margin)) { x = W - margin; y = margin + (pos - (W - 2*margin)); }
    else if (pos < 2*(W - 2*margin) + (H - 2*margin)) { x = W - margin - (pos - (W - 2*margin) - (H - 2*margin)); y = H - margin; }
    else { x = margin; y = H - margin - (pos - 2*(W - 2*margin) - (H - 2*margin)); }

    ctx.fillText(String(i + 1), x + 3, y + size + 2);
  }

  ctx.restore();
}

// === Рисуем текст ===
function drawSource(){
  src.width = cv.width; src.height = cv.height;
  const pad = (+els.paddingPct.value)/100;
  const padX = src.width*pad, padY = src.height*pad;
  sctx.fillStyle = "#000"; sctx.fillRect(0,0,src.width,src.height);

  const lines = els.text.value.replace(/\r/g,'').split('\n');
  let fs = +els.fontSize.value;
  const weight = els.bold.checked ? "700" : "400";
  sctx.textAlign = "center"; sctx.textBaseline = "middle";
  sctx.fillStyle = "#fff";

  sctx.font = `${weight} ${fs}px ${els.fontFamily.value}`;
  const lh = fs * 1.1;
  const cx = src.width/2, cy = src.height/2;
  const startY = cy - (lines.length-1)*lh/2;
  lines.forEach((t,i)=> sctx.fillText(t, cx, startY + i*lh));
}

// === Цвет палитры ===
function pickColor(angle, pal){
  if(pal === 'mono') return '#ffffff';
  if(pal === 'neon') return `hsl(${(angle*180/Math.PI)%360}, 85%, 60%)`;
  if(pal === 'stripes'){
    const band = Math.floor(((angle*180/Math.PI)%360) / 90);
    return stripeColors[band % stripeColors.length];
  }
  return '#fff';
}

function sampleLumaFast(buf, x, y, w, h){
  x = Math.max(0, Math.min(w-1, x));
  y = Math.max(0, Math.min(h-1, y));
  const i = (y*w + x)*4;
  const r = buf[i], g = buf[i+1], b = buf[i+2];
  return 0.2126*r + 0.7152*g + 0.0722*b;
}

// === Анимация радиальных линий ===
function renderFrame(time){
  drawSource();
  ctx.fillStyle = "#000";
  ctx.fillRect(0,0,W,H);

  const pal = els.palette.value;
  var speed = +els.speed.value;
  const aStep = 4 * Math.PI/180;
  const rings = 200;
  const stroke = 6;
  const srcData = sctx.getImageData(0,0,src.width,src.height).data;

  for(let ri=1; ri<=rings; ri++){
    var r = ri * (Math.hypot(W/2,H/2)/rings);
    const animShift = (time/1000 * speed + ri*0.05) % (2*Math.PI);
    for(let a=0; a<2*Math.PI; a+=aStep){
      const angle = a + animShift;
      var x = Math.round(center.x + Math.cos(angle)*r);
      var y = Math.round(center.y + Math.sin(angle)*r);
      const lum = sampleLumaFast(srcData, x, y, src.width, src.height);
      if(lum < 120) continue;
      ctx.strokeStyle = pickColor(angle, pal);
      ctx.lineWidth = stroke;
      ctx.beginPath();
      ctx.arc(center.x, center.y, r, angle, angle + 0.06);
      ctx.stroke();
    }
  }

  drawNumbersAround(time/1000, els.numColor.value, +els.numSize.value, +els.numMargin.value);
  requestAnimationFrame(renderFrame);
}

document.getElementById('download').addEventListener('click', ()=>{
  const a = document.createElement('a');
  a.download = 'radial_january.png';
  a.href = cv.toDataURL();
  a.click();
});

requestAnimationFrame(renderFrame);
</script>
</body>
</html>

